S = "Hakeem Force Academy"
QS = [
(S, "Who developed the first successful inactivated (injectable) polio vaccine?", ["Albert Sabin", "Jonas Salk", "Edward Jenner", "Louis Pasteur"], 1, "Jonas Salk developed the first effective inactivated polio vaccine, which was announced as safe and effective in 1955.", "Albert Sabin later developed the oral polio vaccine, which is the one used in drops in Pakistan.", [449, 5072]),
(S, "Which Pakistani women cricketer was the first to take 100 wickets in women's ODIs?", ["Sana Mir", "Bismah Maroof", "Javeria Khan", "Nain Abidi"], 0, "Sana Mir, former captain of Pakistan women's team, was the first Pakistani woman to reach 100 ODI wickets.", "Sana Mir finished her career with over 150 ODI wickets.", [4833]),
(S, "Khushal Khan Khattak is a famous poet of which language?", ["Punjabi", "Sindhi", "Pashto", "Balochi"], 2, "Khushal Khan Khattak (1613-1689) was a warrior-poet who wrote in Pashto.", "He is regarded as the national poet of the Pashtuns.", [2823]),
(S, "Baba Fariduddin Ganj Shakar is regarded as the first major poet of which language?", ["Punjabi", "Pashto", "Urdu", "Sindhi"], 0, "Baba Farid (1173-1266) of Pakpattan is considered the first major poet of the Punjabi language.", "Some of his verses are included in the Guru Granth Sahib.", [1941]),
(S, "Habba Khatoon was a famous poetess of which language?", ["Kashmiri", "Punjabi", "Pashto", "Sindhi"], 0, "Habba Khatoon (16th century) is known as the Nightingale of Kashmir and wrote in Kashmiri.", "Her real name was Zoon, meaning moon.", [2095]),
(S, "Through which point does the line y = 5x pass?", ["(0, 5)", "(1, 1)", "(5, 1)", "(0, 0)"], 3, "Putting x = 0 gives y = 5 times 0 = 0, so the line passes through (0, 0). The other points do not satisfy y = 5x.", "Any line of the form y = mx passes through the origin.", [1022]),
(S, "Which of the following points lies on the line y = 6x?", ["(2, 8)", "(6, 1)", "(2, 12)", "(1, 12)"], 2, "For (2, 12): 6 times 2 = 12, so it satisfies y = 6x. The others do not.", "The line y = 6x has slope 6 and passes through the origin.", [3082]),
(S, "In which year was the film Jinnah, based on the life of Quaid-e-Azam, released?", ["1988", "1998", "2002", "1994"], 1, "The film Jinnah, directed by Jamil Dehlavi and starring Christopher Lee, was released in 1998.", "Christopher Lee played the role of Muhammad Ali Jinnah in the film.", [2759]),
(S, "What is the population of Pakistan according to the 2023 census?", ["About 207 million", "About 241 million", "About 220 million", "About 260 million"], 1, "The 2023 digital census recorded Pakistan's population as about 241.49 million.", "The 2017 census had recorded about 207.7 million, and candidates in 2022 used estimates of about 220 million.", [3890, 3891, 288, 1203]),
(S, "What is the population of Punjab province according to the 2023 census?", ["About 110 million", "About 99 million", "About 127.7 million", "About 150 million"], 2, "The 2023 census counted about 127.7 million people in Punjab, the most populous province.", "Punjab holds roughly half of Pakistan's population.", [3892]),
(S, "In which province of Pakistan is Gwadar port located?", ["Sindh", "Balochistan", "Khyber Pakhtunkhwa", "Punjab"], 1, "Gwadar is a port city on the Arabian Sea coast in Balochistan.", "Gwadar is the terminal point of the China-Pakistan Economic Corridor (CPEC).", [2564, 4337]),
(S, "Which of the following is a major port of Sri Lanka?", ["Colombo", "Gwadar", "Chittagong", "Karachi"], 0, "Colombo is the largest and busiest port of Sri Lanka.", "Hambantota is another important port of Sri Lanka.", [3803]),
(S, "When did Pakistan issue its first postage stamps?", ["14 August 1947", "9 July 1948", "23 March 1956", "1 January 1950"], 1, "Pakistan's first set of postage stamps was issued on 9 July 1948.", "Before that, British Indian stamps overprinted with the word Pakistan were used in 1947.", [4225]),
(S, "What is the value of x to the power 0 (for x not equal to 0)?", ["0", "x", "1", "Undefined"], 2, "Any non-zero number raised to the power 0 equals 1, because x to the power n divided by x to the power n equals x to the power 0, which equals 1.", "The expression 0 to the power 0 is treated as undefined or indeterminate in many contexts.", [4052]),
(S, "Which countries hold veto power in the UN Security Council?", ["USA, UK, France, Russia, China", "USA, UK, Germany, Japan, India", "USA, Russia, China, India, Brazil", "USA, UK, France, Germany, Italy"], 0, "The five permanent members of the Security Council (P5) have veto power: USA, UK, France, Russia and China.", "A single veto from any permanent member blocks a substantive resolution.", [4421]),
(S, "Who is the chairman of the Pakistan Peoples Party (PPP)?", ["Asif Ali Zardari", "Bilawal Bhutto Zardari", "Yousaf Raza Gilani", "Aseefa Bhutto Zardari"], 1, "Bilawal Bhutto Zardari has been chairman of the PPP since December 2007 and still holds the post.", "Bilawal's father Asif Ali Zardari is the co-chairperson of the party.", [235, 5124]),
(S, "Who is the co-chairperson of the Pakistan Peoples Party (PPP)?", ["Bilawal Bhutto Zardari", "Faryal Talpur", "Asif Ali Zardari", "Nafisa Shah"], 2, "Asif Ali Zardari is the co-chairperson of the PPP.", "He is also the President of Pakistan, serving his second term since March 2024.", [1413]),
(S, "Which regional organization was the predecessor of the Economic Cooperation Organization (ECO)?", ["SAARC", "RCD (Regional Cooperation for Development)", "SEATO", "CENTO"], 1, "RCD, formed in 1964 by Pakistan, Iran and Turkey, was revived and expanded as ECO in 1985.", "Pakistan, Iran and Turkey were the founding members of both RCD and ECO.", [4157]),
(S, "How many compiled copies of the Quran were prepared in the time of Hazrat Abu Bakr (RA)?", ["One", "Three", "Five", "Seven"], 0, "Under Hazrat Abu Bakr (RA) the Quran was collected into one single compiled copy, kept with him and then with Hazrat Umar and Hazrat Hafsa (RA).", "Copies were multiplied and sent to different regions later, during the time of Hazrat Uthman (RA).", [3119]),
(S, "Choose the correct preposition: My father died ___ the war.", ["in", "on", "at", "by"], 0, "We say died in a war, because the war is the event during which he died.", "We say died of an illness but died in an accident or war.", [2851, 3135]),
(S, "What is the meaning of the word prescribe?", ["To forbid completely", "To recommend or order as a remedy or rule", "To copy something", "To hide something"], 1, "To prescribe means to advise or order something, such as a medicine or a rule. Its synonyms include recommend, advise and ordain.", "A doctor writes a prescription to prescribe medicine.", [415, 3983]),
(S, "Which is the present constitution of Pakistan?", ["Constitution of 1956", "Constitution of 1962", "Constitution of 1973", "Constitution of 1935"], 2, "Pakistan is currently governed by the Constitution of 1973, which came into force on 14 August 1973.", "It has been amended many times, including the 18th Amendment in 2010.", [3894]),
(S, "Who was the Prime Minister of Pakistan when the first constitution (1956) was adopted?", ["Liaquat Ali Khan", "Chaudhry Muhammad Ali", "Huseyn Shaheed Suhrawardy", "Muhammad Ali Bogra"], 1, "Chaudhry Muhammad Ali was Prime Minister when the 1956 Constitution was passed and enforced on 23 March 1956.", "Pakistan was declared an Islamic Republic under this constitution.", [1472, 5397, 5395]),
(S, "Who acts as President of Pakistan when the President is absent or unable to work?", ["Chief Justice of Pakistan", "Chairman of the Senate", "Prime Minister", "Speaker of the National Assembly"], 1, "Under Article 49 of the Constitution, the Chairman of the Senate acts as President, and if he is unavailable, the Speaker of the National Assembly does.", "The Chairman of the Senate is elected by the members of the Senate.", [5100]),
(S, "Who is the head of state of Jordan?", ["King Abdullah II", "King Hussein", "Mohammed bin Salman", "Hamad bin Isa"], 0, "Jordan is a monarchy and King Abdullah II is its head of state, so it has no president.", "King Abdullah II has ruled since 1999 after the death of his father King Hussein.", [1427]),
(S, "Who is the head of state of the United Kingdom?", ["The Prime Minister", "King Charles III", "The President", "The Speaker"], 1, "The UK is a monarchy with no president, and King Charles III is the head of state.", "Andy Burnham became Prime Minister in July 2026, and in 2022 candidates named Boris Johnson in this role.", [25]),
(S, "Who is the President of Russia?", ["Dmitry Medvedev", "Vladimir Putin", "Boris Yeltsin", "Sergei Lavrov"], 1, "Vladimir Putin is the President of Russia, in office since 2012 after earlier terms from 2000 to 2008.", "He was re-elected in March 2024 for a term of six years.", [684]),
(S, "Who is the President of the United States?", ["Joe Biden", "Barack Obama", "Donald Trump", "Kamala Harris"], 2, "Donald Trump is the 47th President of the USA, in office since January 2025.", "Joe Biden, named by candidates in 2022, was president from 2021 to 2025.", [130]),
(S, "If the price of 3 eggs is 4 rupees, what is the price of 18 eggs?", ["20 rupees", "22 rupees", "24 rupees", "26 rupees"], 2, "18 eggs is 6 times 3 eggs, so the price is 6 times 4 = 24 rupees.", "This is a direct proportion problem solved by the unitary method.", [2427]),
(S, "Complete the sentence: The prices of clothes are too ___.", ["high", "tall", "long", "big"], 0, "Prices are described as high or low, so high is the correct word.", "We use tall and long for height and length, not for prices.", [800, 3049]),
]
